<section class="auth-section container"><div class="auth-intro"><div class="eyebrow"><?= t('موبايلك هو مفتاحك','YOUR PHONE IS YOUR KEY') ?></div><h1><?= t('أهلاً بيك<br>في <em>حصاد.</em>','Welcome<br>to <em>Hasad.</em>') ?></h1><p><?= t('من غير إيميل أو كلمة مرور. رقم موبايلك ورمز تأكيد، وتتابع بيعك أو طلبات مصنعك من مكان واحد.','No email or password. Your mobile number and a verification code let you track your supply and orders in one place.') ?></p><div class="auth-art"><?= icon('sprout') ?><span>✦</span></div></div><form class="form-card auth-card" method="post" action="<?= e(url('login')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="phone-start"><h2><?= t('دخول / حساب جديد','Sign in / create account') ?></h2><p class="caption"><?= t('هنبعت رمز SMS لتأكيد إن الرقم بتاعك.','We send an SMS code to confirm the number belongs to you.') ?></p><?php field(t('اسمك','Your name'),'name','text','','required maxlength="160" autocomplete="name"');field(t('رقم الموبايل المصري','Egyptian mobile number'),'phone','tel','','required maxlength="30" autocomplete="tel" placeholder="01012345678" dir="ltr"');select_field(t('هتستخدم حصاد إزاي؟','How will you use Hasad?'),'account_type',['seller'=>t('مزارع / بائع مواد','Farmer / material supplier'),'buyer'=>t('مصنع / مشتري مواد','Factory / material buyer')]); ?><label class="consent"><input type="checkbox" name="consent" value="yes" required><span><?= t('أوافق على استلام رمز دخول عبر SMS وعلى ','I agree to receiving an SMS login code and to the ') ?><a href="<?= e(url('privacy')) ?>"><?= t('سياسة الخصوصية','privacy policy') ?></a>.</span></label><button class="button button-green button-full" type="submit"><?= t('ابعت رمز الدخول','Send login code') ?><?= icon('arrow') ?></button><p class="caption"><?= t('لو عندك حساب بنفس الرقم، هتدخل على حسابك الحالي.','If you already have an account with this number, you will sign into that account.') ?></p></form></section>
